import itertools
import numpy as np

n = 17
fixed = {1: -1, 6: 1, 9: -1}  # 0-indexed

def compute_C(seq, k):
    return sum(seq[i] * seq[i+k] for i in range(n - k))

def check(seq):
    # check fixed values
    for idx, val in fixed.items():
        if seq[idx] != val:
            return False
    # compute C_k
    C = [0]*(n)  # index by k, C[0] not used
    for k in range(1, n):
        C[k] = compute_C(seq, k)
    # check fixed C values
    if C[7] != 3:
        return False
    if C[8] != -2:
        return False
    if C[12] != 0:
        return False
    # compute sum of squares
    sos = sum(C[k]**2 for k in range(1, n))
    if sos <= 40:
        return True, C, sos
    return False

# brute force
found = []
for bits in itertools.product([-1, 1], repeat=n):
    seq = list(bits)
    res = check(seq)
    if res:
        found.append((seq, res[1], res[2]))
        print("Found:", seq, "sos:", res[2])
        break

if not found:
    print("No solution found")

