import itertools

n = 17

def compute_C(seq, k):
    return sum(seq[i] * seq[i+k] for i in range(n - k))

def search(fixed_indices):
    # fixed_indices: dict index->value (0-indexed)
    for bits in itertools.product([-1, 1], repeat=n):
        seq = list(bits)
        ok = True
        for idx, val in fixed_indices.items():
            if seq[idx] != val:
                ok = False
                break
        if not ok:
            continue
        C = [0]*n
        for k in range(1, n):
            C[k] = compute_C(seq, k)
        if C[7] != 3:
            continue
        if C[8] != -2:
            continue
        if C[12] != 0:
            continue
        sos = sum(C[k]**2 for k in range(1, n))
        if sos <= 40:
            return seq, C, sos
    return None

# Try 1-indexed: seq[1]=-1 => index 1 (0-indexed) = -1
fixed1 = {1: -1, 6: 1, 9: -1}
print("1-indexed interpretation:")
res = search(fixed1)
if res:
    print("Found:", res[0], "sos:", res[2])
else:
    print("No solution")

# Try 0-indexed: seq[1]=-1 => index 1 (0-indexed) = -1 (same as above)
# Actually "seq[1]=-1" could mean the first element (index 0) if 1-indexed.
# Let's try index 0 = -1, index 5 = 1, index 8 = -1 (if 1-indexed)
# But also could be 0-indexed: seq[1] is index 1.
# Let's try both.

# 0-indexed: seq[1] means index 1 (second element)
fixed0 = {1: -1, 6: 1, 9: -1}  # same as above actually
# Wait, if 0-indexed, seq[1] is the second element. That's same as 1-indexed seq[1]? 
# Actually in 1-indexed, seq[1] is first element. In 0-indexed, seq[1] is second element.
# So we need to distinguish.

# Let's try: 1-indexed => index 0 = -1, index 5 = 1, index 8 = -1
fixed_1idx = {0: -1, 5: 1, 8: -1}
print("\n1-indexed (seq[1] is first element):")
res = search(fixed_1idx)
if res:
    print("Found:", res[0], "sos:", res[2])
else:
    print("No solution")

# 0-indexed: seq[1] is second element => index 1 = -1, index 6 = 1, index 9 = -1
fixed_0idx = {1: -1, 6: 1, 9: -1}
print("\n0-indexed (seq[1] is second element):")
